import time
from concurrent.futures import ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element of xs in a thread pool.

    Returns the results in input order when every element passes.
    If any element fails, raises Bad for the failing element with the
    lowest index, regardless of which worker finishes first.
    """
    with ThreadPoolExecutor() as pool:
        futures = [pool.submit(check, x) for x in xs]
        out: list[int] = []
        for fut in futures:
            out.append(fut.result())
    return out


def test_all_even_returns_results_in_order() -> None:
    assert all_even([2, 4, 6]) == [2, 4, 6]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_all_even_raises_bad_for_odd() -> None:
    with pytest.raises(Bad) as info:
        all_even([2, 3, 4])
    assert info.value.n == 3


def test_all_even_lowest_index_wins_over_completion_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    original_check = check

    def slow_check(x: int) -> int:
        # The bad element at index 0 finishes last; the one at index 1 finishes first.
        if x == 5:
            time.sleep(0.05)
        return original_check(x)

    monkeypatch.setattr(f"{__name__}.check", slow_check)
    with pytest.raises(Bad) as info:
        all_even([5, 3])
    assert info.value.n == 5
